parameters.jsCode:
// Junta el alta con la extraccion, sin fiarse de que venga limpia.
const salida = [];
for (const item of $input.all()) {
  const alta = $('Normalizar alta').first().json;
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let datos;
  try {
    datos = JSON.parse(bruto);
  } catch (error) {
    datos = { partes: [], objeto: null, fecha_fin: null, renovacion: null, preaviso_dias: null, preaviso_respecto_a: null, penalizaciones: [], obligaciones_operativas: [], dudas: ['extraccion no parseable: ' + bruto.slice(0, 150) + ' - extraer a mano'] };
  }
  salida.push({
    json: {
      id: alta.id,
      contraparte: alta.contraparte,
      tipo: alta.tipo,
      archivo: alta.archivo,
      procesable: alta.procesable,
      objeto: datos.objeto ?? '',
      fecha_firma: datos.fecha_firma ?? '',
      fecha_inicio: datos.fecha_inicio ?? '',
      fecha_fin: datos.fecha_fin ?? '',
      renovacion: datos.renovacion ?? 'no_consta',
      preaviso_dias: datos.preaviso_dias ?? '',
      preaviso_respecto_a: datos.preaviso_respecto_a ?? '',
      extraccion: JSON.stringify(datos),
      dudas: (datos.dudas || []).join(' | '),
      estado: 'extraido_sin_revisar',
    },
  });
}
return salida;

