// Avisa a 30, 15 y 5 dias de cada fecha_limite_decision de contratos vigentes.
const UMBRALES = [30, 15, 5];
const hoy = new Date();
const avisos = [];
for (const item of $input.all()) {
  const c = item.json;
  if (String(c.estado || '') !== 'vigente') continue;
  const limite = String(c.fecha_limite_decision || '').slice(0, 10);
  if (!limite) continue;
  const dias = Math.ceil((new Date(limite) - hoy) / 86400000);
  if (dias < 0) {
    avisos.push('VENCIDA SIN DECISION: ' + c.contraparte + ' (' + (c.objeto || c.tipo) + '). La fecha limite era el ' + limite + '. Mira que opciones quedan, hoy.');
  } else if (UMBRALES.includes(dias)) {
    avisos.push('Quedan ' + dias + ' dias para decidir sobre ' + c.contraparte + ' (' + (c.objeto || c.tipo) + '). Fecha limite: ' + limite + '. Si no haces nada: ' + (c.renovacion === 'tacita' ? 'se renueva solo' : c.renovacion === 'expresa' ? 'pierde vigencia' : 'revisa la clausula') + '. Contrato: ' + (c.archivo || 'ver inventario'));
  }
}
if (avisos.length === 0) {
  return [];
}
return [{ json: { texto: 'Contratos: fechas limite\n\n' + avisos.join('\n\n'), avisos: avisos.length } }];
